// Generated by Suite Builder from a crawl of the site. Asks an address for its answer, without loading it in the page.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
/** What an address answered: its status, and the address it ended up at after redirects. */
export interface Answer {
  status: number;
  url: string;
  ok: boolean;
}

/**
 * Asks an address for its answer without loading it in the page (cy.request): what a link check
 * needs (does /careers answer, and where does it end up after redirects?).
 */
export const Http = {
  get(url: string): Cypress.Chainable<Answer> {
    return cy.request({ url, failOnStatusCode: false, followRedirect: true }).then((response) => {
      // Each redirect is "301: https://...": the last one says where it ended up.
      const last = response.redirects?.[response.redirects.length - 1];
      const at = last ? last.slice(last.indexOf(': ') + 2) : url;
      return { status: response.status, url: at, ok: response.status >= 200 && response.status < 300 };
    });
  },
};
